# -*- coding: utf-8 -*-
"""
migrate_cover_updates.py - Migracion idempotente de portadas.
Actualiza las portadas de los libros 177 y 178.

Ejecucion:
    cd backend
    python migrate_cover_updates.py

Requiere DATABASE_URL en variables de entorno.
"""
import base64
import os
import sys
import uuid


COVERS = {
    177: {
        "title": "Anaconda y otros cuentos",
        "author": "Horacio Quiroga",
        "ext": "png",
        "b64": "",
        "expected_size": 1075207,
    },
    178: {
        "title": "César o nada",
        "author": "Pío Baroja",
        "ext": "png",
        "b64": "",
        "expected_size": 1661015,
    },
}


def log(msg):
    print("[COVERS] " + str(msg), flush=True)


def get_db():
    import psycopg2
    import psycopg2.extras
    db_url = os.getenv("DATABASE_URL")
    if not db_url:
        log("ERROR: DATABASE_URL no configurada.")
        sys.exit(1)
    conn = psycopg2.connect(db_url)
    conn.autocommit = False
    psycopg2.extras.register_uuid(conn)
    return conn


def migrate_covers():
    log("=== Inicio de migracion de portadas ===")
    log("IDs objetivo: 177, 178")
    log("")

    conn = get_db()
    cursor = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)

    cursor.execute(
        "SELECT id, title, author, cover_image_url FROM books WHERE id IN (177, 178)"
    )
    rows = {r["id"]: r for r in cursor.fetchall()}

    if not rows:
        log("ERROR: No se encontraron los libros 177 ni 178.")
        conn.close()
        sys.exit(1)

    for book_id in [177, 178]:
        if book_id not in rows:
            log("ERROR: Libro %d no encontrado." % book_id)
            conn.close()
            sys.exit(1)

    info_177 = rows[177]
    info_178 = rows[178]

    if info_177["title"] != "Anaconda y otros cuentos":
        log("ERROR: ID 177 titulo inesperado: '%s'" % info_177["title"])
        conn.close()
        sys.exit(1)
    if info_177["author"] != "Horacio Quiroga":
        log("ERROR: ID 177 autor inesperado: '%s'" % info_177["author"])
        conn.close()
        sys.exit(1)
    if info_178["title"] != "César o nada":
        log("ERROR: ID 178 titulo inesperado: '%s'" % info_178["title"])
        conn.close()
        sys.exit(1)
    if info_178["author"] != "Pío Baroja":
        log("ERROR: ID 178 autor inesperado: '%s'" % info_178["author"])
        conn.close()
        sys.exit(1)

    log("Verificacion de titulos y autores: OK")
    log("")

    from storage_config import STORAGE_COVERS
    os.makedirs(STORAGE_COVERS, exist_ok=True)
    log("Directorio de portadas: %s" % STORAGE_COVERS)

    updated_count = 0
    for book_id in [177, 178]:
        info = rows[book_id]
        cover = COVERS[book_id]
        current_url = info["cover_image_url"] or ""

        log("--- ID %d: %s ---" % (book_id, cover["title"]))
        log("cover_image_url actual: %s" % current_url)

        if "/static/covers/" in current_url and "migrated_" in current_url:
            log("ID %d ya tiene portada migrada. Saltando." % book_id)
            log("")
            continue

        log("Decodificando imagen...")
        image_data = base64.b64decode(cover["b64"])
        log("Tamano: %d bytes" % len(image_data))

        expected = cover["expected_size"]
        if len(image_data) != expected:
            log("ERROR: Tamano inesperado: %d bytes (esperado %d)" % (len(image_data), expected))
            conn.close()
            sys.exit(1)

        filename = "migrated_" + uuid.uuid4().hex + "." + cover["ext"]
        filepath = os.path.join(STORAGE_COVERS, filename)

        log("Escribiendo portada: %s" % filename)
        with open(filepath, "wb") as f:
            f.write(image_data)

        if not os.path.exists(filepath):
            log("ERROR: Archivo no creado: %s" % filepath)
            conn.close()
            sys.exit(1)

        written_size = os.path.getsize(filepath)
        if written_size != len(image_data):
            log("ERROR: Tamano incorrecto: %d bytes (esperado %d)" % (written_size, len(image_data)))
            conn.close()
            sys.exit(1)

        log("Archivo verificado: %d bytes OK" % written_size)

        new_url = "/static/covers/" + filename
        log("Actualizando BD: cover_image_url = %s" % new_url)
        cursor.execute(
            "UPDATE books SET cover_image_url = %s WHERE id = %s",
            (new_url, book_id),
        )

        if cursor.rowcount != 1:
            log("ERROR: UPDATE afecto %d filas (esperado 1)" % cursor.rowcount)
            conn.close()
            sys.exit(1)

        log("ID %d OK" % book_id)
        log("")
        updated_count += 1

    if updated_count > 0:
        conn.commit()
        log("=== Migracion completada: %d portadas actualizadas ===" % updated_count)
    else:
        log("=== No se necesitaron actualizaciones (ya migradas) ===")

    log("")
    log("=== Verificacion final ===")
    cursor.execute(
        "SELECT id, title, author, cover_image_url FROM books WHERE id IN (177, 178)"
    )
    final_rows = cursor.fetchall()
    for r in final_rows:
        log("ID %d: %s | cover_image_url = %s" % (r["id"], r["title"], r["cover_image_url"]))

    for r in final_rows:
        url = r["cover_image_url"] or ""
        if "/static/covers/" in url:
            fname = url.split("/")[-1]
            fpath = os.path.join(STORAGE_COVERS, fname)
            if os.path.exists(fpath):
                log("Archivo %s: %d bytes OK" % (fname, os.path.getsize(fpath)))
            else:
                log("ERROR: Archivo no encontrado: %s" % fpath)

    conn.close()
    log("=== Fin ===")


if __name__ == "__main__":
    migrate_covers()
